import React, { useEffect, useState } from 'react'
import useApi from '../../../../hooks/useApi'
import hospitalsApi from '../../../../api/hospitals/hospitalsApi'
import { Collapse } from 'antd'

export default function RadiologyOrdersHistory({ selectedAdmission, selectedDependant }) {

  const [dependantRadiologyOrders, setdependantRadiologyOrders] = useState([])

  const [data, setData] = useState([])

  const getDependantRadiologyOrdersApi = useApi(hospitalsApi.hospitalStaffAction)
  const getDependantRadiologyOrders = async () => {
    await getDependantRadiologyOrdersApi.request({
      "action": "GetDependantRadiologyOrders",
      "dependant": selectedDependant.id
    })
  }
  useEffect(() => {
    if (selectedDependant) {

      getDependantRadiologyOrders()
    }

  }, [selectedDependant])
  useEffect(() => {
    if (getDependantRadiologyOrdersApi.data) {
      if (getDependantRadiologyOrdersApi.data.length) {
        setdependantRadiologyOrders(getDependantRadiologyOrdersApi.data)
      }
    }

    console.log("getDependantRadiologyOrdersApi.data", getDependantRadiologyOrdersApi.data)
  }, [getDependantRadiologyOrdersApi.data])


  useEffect(() => {
    if (dependantRadiologyOrders) {
      if (dependantRadiologyOrders.length) {
        setData(dependantRadiologyOrders.map((i, index) => ({
          label: `${i.created}  ${i.destination_department_title}`,
          key: index,
          children: <div>
            {
              i.examinations && i.examinations.length ? <div>

                {
                  i.examinations.map((y,yIn) => {
                    return <div>
                      <p className=''>
                      <span className='mx-2'>{yIn+1}.</span>
                      <span className='mx-2'>{y.examination_title}</span>
                      <span className='mx-2 font-semibold'>KES {parseFloat(y.examination_charge).toFixed(2).toString()}</span>
                      </p>

                    </div>
                  })
                }
              </div> : <div></div>
            }
          </div>
        })))
      }
    }

    console.log("getDependantLaboratoryOrdersApi.data", getDependantRadiologyOrdersApi.data)
  }, [dependantRadiologyOrders])
  return (
    <div>
      <p className='text-center text-xl font-semibold'>Radiology Orders</p>

      {data && data.length ? <Collapse items={data} defaultActiveKey={['1']} /> : <></>}

    </div>
  )
}
