import React, { useEffect, useState } from 'react'
import { toast, ToastContainer } from 'react-toastify'
import useApi from '../../../../hooks/useApi'
import dependantsApi from '../../../../api/dependantsApi'
import hospitalsApi from '../../../../api/hospitals/hospitalsApi'
import { useLocation } from 'react-router-dom'
import { useStateContext } from '../../../../contexts/ContextProvider'
import * as Yup from "yup";
import { useFormik } from "formik";
import { CustomForm, CustomFormItem, CustomSelectReactSelect, CustomTextArea } from '../../../../components'
import departmentsApi from '../../../../api/departmentsApi'
import LaboratoryOrdersForm from '../../visitors/LaboratoryOrdersForm'
import LaboratoryOrdersHistory from './LaboratoryOrdersHistory'
import PhysiotherapyOrdersHistory from './PhysiotherapyOrdersHistory'
import RadiologyOrdersHistory from './RadiologyOrdersHistory'
import RadiologyOrdersForm from '../../visitors/RadiologyOrdersForm'
import PhysiotherapyOrdersForm from '../../visitors/PhysiotherapyOrdersForm'

export default function DepartmentalOrders() {
  const { currentColor, loggedInUser } = useStateContext()

  const [openLaboratoryOrder, setopenLaboratoryOrder] = useState();
  const [openRadiologyOrder, setopenRadiologyOrder] = useState();
  const [openPhysiotherapyOrder, setopenPhysiotherapyOrder] = useState();
  const [selectedAdmission, setselectedAdmission] = useState()
  const [selectedDependant, setselectedDependant] = useState()
  const [dischargeSummary, setdischargeSummary] = useState()
  const [errors, setErrors] = useState([])
  const [showForm, setshowForm] = useState(dischargeSummary ? false : true)

  const [updated, setupdated] = useState(false)
  const location = useLocation()
  const [selectedDependantId, setselectedDependantId] = useState()
  useEffect(() => {
    setselectedDependantId(location.state.dependant)
  }, [location])


  //Get departments
  //Retrieve departments
  const [departments, setDepartments] = useState([]);
  const entityDepartmentsApi = useApi(departmentsApi.departmentsAction);
  const getEntityDepartments = async (user) => {
    await entityDepartmentsApi.request({
      action: "GetEntityDepartments",
      entity: user.entity_id,
    });
  };


  useEffect(() => {
    if (loggedInUser != null) {
      getEntityDepartments(loggedInUser);
    }

  }, [loggedInUser]);




  useEffect(() => {
    if (entityDepartmentsApi.data && entityDepartmentsApi.data.length) {
      setDepartments(
        entityDepartmentsApi.data
          .filter((x) => x.id !== loggedInUser.employment_department)
          .map((i) => ({
            label: i.title,
            value: i.id,
            department_type: i.department_type,
          }))
      );
    }
    console.log("entityDepartmentsApi", entityDepartmentsApi.data);
  }, [entityDepartmentsApi.data]);


  //Create Laboratory Order
  //Create dependant order
  const createDependantOrderApi = useApi(hospitalsApi.hospitalStaffAction);

  const createDependantOrder = async (data) => {
    setErrors([])
    await createDependantOrderApi.request(data);
  };



  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);

  useEffect(() => {
    if (createDependantOrderApi.data) {

      if (createDependantOrderApi.data.laboratory_order) {
        setopenLaboratoryOrder(createDependantOrderApi.data.laboratory_order)
      }
      if (createDependantOrderApi.data.radiology_order) {
        setopenRadiologyOrder(createDependantOrderApi.data.radiology_order)
      }
      if (createDependantOrderApi.data.physiotherapy_order) {
        setopenPhysiotherapyOrder(createDependantOrderApi.data.physiotherapy_order)
      }

      if (createDependantOrderApi.data.errors) {
        setErrors(createDependantOrderApi.data.errors)
      }

    }
    console.log("createDependantOrderApi.data", createDependantOrderApi.data)
  }, [createDependantOrderApi.data])





  //Get admission

  const getAdmissionApi = useApi(hospitalsApi.hospitalInpatientAction)
  const getDependantAdmission = async (id) => {
    await getAdmissionApi.request({
      "action": "GetDependantAdmission",
      "dependant": id
    })
  }

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);
  useEffect(() => {
    if (getAdmissionApi.data) {

      if (getAdmissionApi.data.admission) {
        setselectedAdmission(getAdmissionApi.data.admission)
        toast.success(getAdmissionApi.data.response_message)
      }
    }

    console.log("getAdmissionApi.data", getAdmissionApi.data)
  }, [getAdmissionApi.data])


  const getDependantDetailsApi = useApi(dependantsApi.dependantsAction)
  const getDependantDetails = async (id) => {
    await getDependantDetailsApi.request({
      "action": "GetDependantDetails",
      "dependant_id": id
    })
  }


  useEffect(() => {
    if (getDependantDetailsApi.data) {
      if (getDependantDetailsApi.data.dependant) {
        setselectedDependant(getDependantDetailsApi.data.dependant)
        toast.success(getDependantDetailsApi.data.response_message)
      }
    }
    console.log("getDependantDetailsApi.data", getDependantDetailsApi.data)
  }, [getDependantDetailsApi.data])


  useEffect(() => {
    if (selectedDependantId) {
      getDependantAdmission(selectedDependantId)
      getDependantDetails(selectedDependantId);
      console.log("selectedDependantId", selectedDependantId)
    }

  }, [selectedDependantId])

  useEffect(() => {
    if (selectedAdmission) {

      // getAdmissionOrCreatePrescription(selectedAdmission.id);

    }

  }, [selectedAdmission])

  const prescriptionFormik = useFormik({
    initialValues: {
      department: "",
    },

    validationSchema: Yup.object({
      department: Yup.object().required("Select destination department"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);
      let data = null;


      if (values.department.department_type === "LABORATORY") {
        toast.success("Pathology");
        data = {
          action: "CreateLaboratoryOrder",
          origin_department: values.department.value,
          destination_department: loggedInUser.employment_department,
          dependant: selectedDependant.id,
          admission:selectedAdmission.id
        };

      } else if (values.department.department_type === "RADIOLOGY") {

        data = {
          action: "CreateRadiologyOrder",
          origin_department: values.department.value,
          destination_department: loggedInUser.employment_department,
          dependant: selectedDependant.id,
          admission:selectedAdmission.id
        };
        console.log("data at rad",data)

      } else if (values.department.department_type === "PHYSIOTHERAPY") {

        data = {
          action: "CreatePhysiotherapyOrder",
          origin_department: values.department.value,
          destination_department: loggedInUser.employment_department,
          dependant: selectedDependant.id,
          admission:selectedAdmission.id
        };

      }

      console.log("DATA", data)
      createDependantOrder(data)
    },
  });

  return (
    <div>

      <ToastContainer theme='light' position='bottom-center' />
      <div className=" rounded-sm border-gray-200 mt-5 border-2 bg-white">
        <p className="text-center text-xl font-semibold">
          Add New Departmental Order
        </p>
        <CustomForm
          layout="horizontal"
          handleFinish={prescriptionFormik.handleSubmit}
          className="grid grid-cols-1 md:grid-cols-3 gap-4  justify-center items-center w-full px-2 "
        >
          <CustomFormItem
            className="w-full h-14"
            touched={prescriptionFormik.touched.department}
            error={prescriptionFormik.errors.department}
          >
            <CustomSelectReactSelect
              className="text-start w-full h-full"
              name="department"
              id="department"
              label="Select destination department"
              size="large"
              onChange={(value) =>
                prescriptionFormik.setFieldValue("department", value)
              }
              value={prescriptionFormik.values.department}
              placeholder="Select destination department"
              options={departments}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={prescriptionFormik.touched.referral_comment}
            error={prescriptionFormik.errors.referral_comment}
          >
            <CustomTextArea
              className="text-start"
              id="referral_comment"
              name="referral_comment"
              onChange={prescriptionFormik.handleChange}
              placeholder="Enter referral comment (optional)"
              label="Enter referral comment (optional)"
              size="large"
              type="text"
              value={prescriptionFormik.values.referral_comment}
            />
          </CustomFormItem>

          <button
            id="formikPrescription"
            style={{ background: currentColor }}
            className="w-full h-12  rounded-md m-auto text-white self-center flex-1"
            color="primary"
            type="submit"
          >
            Submit
          </button>
        </CustomForm>

        {openLaboratoryOrder && selectedDependant ? <LaboratoryOrdersForm openLaboratoryOrder={openLaboratoryOrder} selectedDependant={selectedDependant} setopenLaboratoryOrder={setopenLaboratoryOrder} /> : <div></div>}
        {openRadiologyOrder && selectedDependant ? <RadiologyOrdersForm openRadiologyOrder={openRadiologyOrder} selectedDependant={selectedDependant} setopenRadiologyOrder={setopenRadiologyOrder} /> : <div></div>}
        {openPhysiotherapyOrder && selectedDependant ? <PhysiotherapyOrdersForm openPhysiotherapyOrder={openPhysiotherapyOrder} selectedDependant={selectedDependant} setopenPhysiotherapyOrder={setopenPhysiotherapyOrder} /> : <div></div>}
      </div>
      <div>
        <LaboratoryOrdersHistory selectedAdmission={selectedAdmission} selectedDependant={selectedDependant} />
        <PhysiotherapyOrdersHistory selectedAdmission={selectedAdmission} selectedDependant={selectedDependant} />
        <RadiologyOrdersHistory selectedAdmission={selectedAdmission} selectedDependant={selectedDependant} />
      </div>
    </div>
  )
}
