import React, { useEffect, useState } from 'react'
import useApi from '../../../../hooks/useApi'
import hospitalsApi from '../../../../api/hospitals/hospitalsApi'
import { Collapse } from 'antd'

export default function LaboratoryOrdersHistory({ selectedAdmission, selectedDependant }) {

  const [dependantlaboratoryOrders, setdependantlaboratoryOrders] = useState([])

  const [data, setData] = useState([])

  const getDependantLaboratoryOrdersApi = useApi(hospitalsApi.hospitalStaffAction)
  const getDependantLaboratoryOrders = async () => {
    setdependantlaboratoryOrders([])
    setData([])
    await getDependantLaboratoryOrdersApi.request({
      "action": "GetDependantLaboratoryOrders",
      "dependant": selectedDependant.id
    })
  }
  useEffect(() => {
    if (selectedDependant) {

      getDependantLaboratoryOrders()
    }

  }, [selectedDependant])
  useEffect(() => {
    if (getDependantLaboratoryOrdersApi.data) {
      if (getDependantLaboratoryOrdersApi.data.length) {
        setdependantlaboratoryOrders(getDependantLaboratoryOrdersApi.data)
       
      }
    }

    console.log("getDependantLaboratoryOrdersApi.data", getDependantLaboratoryOrdersApi.data)
  }, [getDependantLaboratoryOrdersApi.data])


  useEffect(() => {
    if (dependantlaboratoryOrders) {
      if (dependantlaboratoryOrders.length) {
        setData([])
        setData(dependantlaboratoryOrders.map((i, index) => ({
          label: `${i.created}  ${i.destination_department_title}`,
          key: index,
          children: <div>
            {
              i.examinations && i.examinations.length ? <div>

                {
                  i.examinations.map((y,yIn) => {
                    return <div>
                      <p className=''>
                      <span className='mx-2'>{yIn+1}.</span>
                      <span className='mx-2'>{y.examination_name}</span>
                      <span className='mx-2 font-semibold'>KES {parseFloat(y.examination_charge).toFixed(2).toString()}</span>
                      </p>

                    </div>
                  })
                }
              </div> : <div></div>
            }
          </div>
        })))
      }
    }

    console.log("getDependantLaboratoryOrdersApi.data", getDependantLaboratoryOrdersApi.data)
  }, [dependantlaboratoryOrders])
  return (
    <div>
      <p className='text-center text-xl font-semibold'>Laboratory Orders</p>

      {data && data.length ? <Collapse items={data} defaultActiveKey={['1']} />: <></>}

    </div>
  )
}
