import React, { useEffect, useState } from 'react'
import useApi from '../../../../hooks/useApi'
import hospitalsApi from '../../../../api/hospitals/hospitalsApi'
import { Collapse } from 'antd'

export default function PhysiotherapyOrdersHistory({selectedAdmission,selectedDependant}) {
    const [dependantPhysiotherapyOrders, setdependantPhysiotherapyOrders] = useState([])
  
    const [data, setData] = useState([])
  
    const getDependantPhysiotherapyOrdersApi = useApi(hospitalsApi.hospitalStaffAction)
    const getDependantPhysiotherapyOrders = async () => {
      await getDependantPhysiotherapyOrdersApi.request({
        "action": "GetDependantPhysiotherapyOrders",
        "dependant": selectedDependant.id
      })
    }
    useEffect(() => {
      if (selectedDependant) {
  
        getDependantPhysiotherapyOrders()
      }
  
    }, [selectedDependant])
    useEffect(() => {
      if (getDependantPhysiotherapyOrdersApi.data) {
        if (getDependantPhysiotherapyOrdersApi.data.length) {
          setdependantPhysiotherapyOrders(getDependantPhysiotherapyOrdersApi.data)
        }
      }
  
      console.log("getDependantRadiologyOrdersApi.data", getDependantPhysiotherapyOrdersApi.data)
    }, [getDependantPhysiotherapyOrdersApi.data])
  
  
    useEffect(() => {
      if (dependantPhysiotherapyOrders) {
        if (dependantPhysiotherapyOrders.length) {
          setData(dependantPhysiotherapyOrders.map((i, index) => ({
            label: `${i.created}  ${i.destination_department_title}`,
            key: index,
            children: <div>
              {
                i.procedures && i.procedures.length ? <div>
  
                  {
                    i.procedures.map((y,yIn) => {
                      return <div>
                        <p className=''>
                        <span className='mx-2'>{yIn+1}.</span>
                        <span className='mx-2'>{y.procedure_title}</span>
                        <span className='mx-2 font-semibold'>KES {parseFloat(y.charge).toFixed(2).toString()}</span>
                        </p>
  
                      </div>
                    })
                  }
                </div> : <div></div>
              }
            </div>
          })))
        }
      }
  
      console.log("dependantPhysiotherapyOrders.data", getDependantPhysiotherapyOrdersApi.data)
    }, [dependantPhysiotherapyOrders])
  return (
    <div>
          <p className='text-center text-xl font-semibold'>Physiotherapy Orders</p>
    
          {data && data.length ? <Collapse items={data} defaultActiveKey={['1']} /> : <></>}
    
        </div>
  )
}
